using Database.Interfaces;
using Database.Models;
using System;
using System.Collections.ObjectModel;
using System.Linq;

namespace Database.Repositories.InMemory;

public sealed class InMemoryOperationRepository : InMemoryRepository<Operation, int>, IOperationRepository
{
    /// <summary>Operation ids are generated by the application (see UniqueIdGenerator), not by the table.</summary>
    protected override bool UsesIdentity => false;

    public bool HasAnyRow()
    {
        lock (SyncRoot)
        {
            return Items.Count > 0;
        }
    }

    public ReadOnlyCollection<Operation> SelectGroupOperations(long groupId, long userEventId)
    {
        lock (SyncRoot)
        {
            var operationIds = InMemoryStore<Permission>.Items
                .Where(permission => permission.GroupId == groupId && permission.UserEventId == userEventId && permission.OperationId.HasValue)
                .Select(permission => permission.OperationId.Value)
                .ToList();
            return Copy(Items.Where(operation => operationIds.Contains(operation.Id)));
        }
    }

    /// <summary>Supports the "WHERE Id IN @Ids" query: <c>SelectWhere(new { Ids = operationIds })</c>.</summary>
    public override ReadOnlyCollection<Operation> SelectWhere(object param)
    {
        if (!TryGetParam(param, "Ids", out var ids))
        {
            return base.SelectWhere(param);
        }

        var idSet = ToNumberSet(ids);
        lock (SyncRoot)
        {
            return Copy(Items.Where(operation => idSet.Contains(operation.Id)));
        }
    }

    protected override void OnDeleted(Operation operation)
    {
        new InMemoryPermissionRepository().DeleteWhere(new { OperationId = operation.Id });
        new InMemoryInputOutputPortRuleRepository().DeleteWhere(new { OperationId = operation.Id });
    }
}

public sealed class InMemoryUserEventRepository : InMemoryRepository<UserEvent, int>, IUserEventRepository
{
    public UserEvent GetByName(string name)
    {
        lock (SyncRoot)
        {
            var userEvent = Items.FirstOrDefault(existing => String.Equals(existing.Name, name, StringComparison.OrdinalIgnoreCase));
            return userEvent == null ? null : Copy(new[] { userEvent }).First();
        }
    }

    protected override void OnDeleted(UserEvent userEvent)
    {
        new InMemoryPermissionRepository().DeleteWhere(new { UserEventId = userEvent.Id });
        new InMemoryCameraPermissionRepository().DeleteWhere(new { UserEventId = userEvent.Id });
        new InMemoryInputOutputPortRuleRepository().DeleteWhere(new { UserEventId = userEvent.Id });
    }
}
